<script setup>
import { onMounted, ref } from 'vue'
import BrandHeader from '@/components/BrandHeader.vue'
import Icon from '@/components/Icon.vue'
import { getStudyData, action } from '@/services/app'
import { getMyCourses, getCourseDetail, getProgressList, checkIn, getTodayAttendance } from '@/api/education'
import { getMemberUserInfo } from '@/api/member'
import { FRONTEND_DEMO_ENABLED } from '@/config'
import { requireLogin } from '@/utils/auth'

const attendanceDays = [{ label: '周一', date: '07', done: true }, { label: '周二', date: '08', done: true }, { label: '周三', date: '09', done: true }, { label: '周四', date: '10', done: true }, { label: '周五', date: '11', done: true }, { label: '周六', date: '12', done: true }, { label: '周日', date: '13', done: false }]
const data = ref({ photos: {} })
const records = ref([])
const myCourses = ref([])
const firstCourse = ref(null)
const attendanceText = ref('登录后签到')

onMounted(async () => {
  const fallback = await getStudyData()
  data.value = fallback
  try {
    const user = await getMemberUserInfo()
    data.value = { ...fallback, name: user?.nickname || fallback.name, code: user?.id ? `USER-${user.id}` : fallback.code, photos: { ...fallback.photos, avatar: user?.avatar || fallback.photos?.avatar } }
  } catch (error) {}
  try {
    const courses = await getMyCourses()
    firstCourse.value = courses?.[0]
    records.value = (courses || []).map(item => ({ title: `课程 ${item.courseId}`, time: item.grantTime || '已开通' }))
    myCourses.value = await Promise.all((courses || []).map(async item => { const detail = await getCourseDetail(item.courseId).catch(() => null); const progress = await getProgressList(item.courseId).catch(() => []); return { ...item, title: detail?.title, completed: (progress || []).filter(row => row.completed).length } }))
    if (firstCourse.value) { const today = await getTodayAttendance(firstCourse.value.courseId); attendanceText.value = today ? '已签到' : '待签到' }
  } catch (error) { attendanceText.value = '登录后签到' }
})
const openCourse = courseId => uni.navigateTo({ url: `/pages/learn/player?courseId=${courseId}` })
const todayCheckIn = async () => { if (!requireLogin('/pages/study/index')) return; if (!firstCourse.value) return uni.showToast({ title: '请先购买课程', icon: 'none' }); if (FRONTEND_DEMO_ENABLED) return uni.showToast({ title: '体验版仅供浏览，签到记录不会保存', icon: 'none' }); try { await checkIn(firstCourse.value.courseId); attendanceText.value = '已签到'; uni.showToast({ title: '签到成功', icon: 'success' }) } catch (error) { uni.showToast({ title: error.message || '签到失败', icon: 'none' }) } }
</script>

